<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\ThemeAsset\Application\Service\Visibility;

use Psr\EventDispatcher\EventDispatcherInterface;
use Iterator;
use Throwable;
use Civi\Lughauth\Features\Document\Theme\Application\Service\Visibility\ThemeVisibilityService;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ThemeAssetRef;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ThemeAssetAttributes;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ThemeAsset;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\Gateway\ThemeAssetFilter;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\Gateway\ThemeAssetCursor;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\Gateway\ThemeAssetReadGateway;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\Gateway\ThemeAssetSlide;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\Gateway\ThemeAssetWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class ThemeAssetVisibilityService
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly ThemeAssetReadGateway $readGateway,
        private readonly ThemeAssetWriteGateway $writeGateway,
        private readonly ThemeVisibilityService $themeVisibilityService
    ) {
    }

    public function prepareVisibleDataInList(ThemeAsset $content): ThemeAssetAttributes
    {
        return $this->prepareVisibleDataCallback($content, true);
    }
    public function prepareVisibleData(ThemeAsset $content): ThemeAssetAttributes
    {
        return $this->prepareVisibleDataCallback($content, false);
    }
    public function copyWithFixed(ThemeAssetAttributes $attributes, ?ThemeAsset $original = null): ThemeAssetAttributes
    {
        $this->logDebug("Copy with fixed for Theme asset");
        $span = $this->startSpan("Copy with fixed for  Theme asset");
        try {
            $visible = $this->visiblesReferences($attributes);
            $fixed = $this->fieldsToFix($original);
            foreach ($fixed as $field) {
                $visible->unset($field);
            }
            $result = $this->dispatcher->dispatch(new ThemeAssetPresetValues($attributes, $original));
            return $result->attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function copyWithHidden(ThemeAssetAttributes $attributes, ?ThemeAsset $original = null): ThemeAssetAttributes
    {
        $this->logDebug("Copy with hidden for Theme asset");
        $span = $this->startSpan("Copy with hidden for  Theme asset");
        try {
            $hidden = $this->fieldsToHide($original);
            foreach ($hidden as $field) {
                $attributes->unset($field);
            }
            return $attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function checkVisibility(Iterator|string|ThemeAssetRef $value): bool
    {
        $this->logDebug("Check visibility of an iterator for Theme asset");
        $span = $this->startSpan("Check visibility of an iterator for  Theme asset");
        try {
            if (is_string($value)) {
                return !!$this->retrieveVisibleForUpdate(new ThemeAssetRef($value));
            } elseif ($value instanceof ThemeAssetRef) {
                return !!$this->retrieveVisibleForUpdate($value);
            } elseif ($value instanceof Iterator) {
                $ids = [];
                foreach ($value as $val) {
                    $ids[] = $val->uid();
                }
                $filter = new ThemeAssetFilter(uids: $ids);
                return count($ids) == $this->countVisibles($filter);
            } else {
                return false;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function listVisibles(ThemeAssetFilter $filter, ?ThemeAssetCursor $cursor = null): ThemeAssetSlide
    {
        $this->logDebug("List visibles for Theme asset");
        $span = $this->startSpan("List visibles for  Theme asset");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            $result = $this->readGateway->list($visibleFilter, $cursor);
            return $result->slide(function (ThemeAsset $item): bool {
                return $this->evaluatePostVisibility($item);
            });
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function countVisibles(ThemeAssetFilter $filter): int
    {
        $this->logDebug("Count visibles for Theme asset");
        $span = $this->startSpan("Count visibles for  Theme asset");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            return $this->readGateway->count($visibleFilter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function listVisiblesForUpdate(ThemeAssetFilter $filter, ?ThemeAssetCursor $cursor = null): ThemeAssetSlide
    {
        $this->logDebug("List visibles for update for Theme asset");
        $span = $this->startSpan("List visibles for update for  Theme asset");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            $result = $this->writeGateway->listForUpdate($visibleFilter, $cursor);
            return $result->slide(function (ThemeAsset $item): bool {
                return $this->evaluatePostVisibility($item);
            });
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function countVisiblesForUpdate(ThemeAssetFilter $filter): int
    {
        $this->logDebug("Count visibles for update for Theme asset");
        $span = $this->startSpan("Count visibles for update for  Theme asset");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            return $this->writeGateway->countForUpdate($visibleFilter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieveVisible(ThemeAssetRef $ref): ?ThemeAsset
    {
        $this->logDebug("Retrieve visible for Theme asset");
        $span = $this->startSpan("Retrieve visible for  Theme asset");
        try {
            $filter = new ThemeAssetFilter(uids: [$ref->uid()]);
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            if ($readed = $this->readGateway->retrieve($visibleFilter)) {
                return $this->evaluatePostVisibility($readed) ? $readed : null;
            } else {
                return null;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieveVisibleForUpdate(ThemeAssetRef $ref): ?ThemeAsset
    {
        $this->logDebug("Retrieve visible for update for Theme asset");
        $span = $this->startSpan("Retrieve visible for update for  Theme asset");
        try {
            $filter = new ThemeAssetFilter(uids: [$ref->uid()]);
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            if ($readed = $this->writeGateway->retrieveForUpdate($visibleFilter)) {
                return $this->evaluatePostVisibility($readed) ? $readed : null;
            } else {
                return null;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function fieldsToFix(?ThemeAssetRef $ref = null): array
    {
        $this->logDebug("Check fields to fix for Theme asset");
        $span = $this->startSpan("Check fields for fix for Theme asset");
        try {
            $result = $this->dispatcher->dispatch(new ThemeAssetCollectNonEditableFields(ThemeAsset::calculatedFields(), $ref));
            return array_values(array_unique(array_merge($this->fieldsToHide($ref), $result->fields)));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function fieldsToHide(?ThemeAssetRef $ref = null): array
    {
        $this->logDebug("Check fields to hide for Theme asset");
        $span = $this->startSpan("Check fields to hide for  Theme asset");
        try {
            $result = $this->dispatcher->dispatch(new ThemeAssetCollectNonVisibleFields([], $ref));
            return array_values(array_unique($result->fields));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    private function visiblesReferences(ThemeAssetAttributes $attributes): ThemeAssetAttributes
    {
        $this->logDebug("Check visibility of parent references for Theme asset");
        $span = $this->startSpan("Check visibility of parent references for  Theme asset");
        try {
            $theme = $attributes->getTheme();
            if (null !== $theme && !$this->themeVisibilityService->checkVisibility($theme)) {
                throw new NotFoundException("Unknown Theme " . ($theme->uid() ?? 'no-id'));
            }
            return $attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function applyPreVisibilityFilter(ThemeAssetFilter $filter): ThemeAssetFilter
    {
        $this->logDebug("Compose visibility filter for Theme asset");
        $span = $this->startSpan("Compose visibility filter for  Theme asset");
        try {
            $result = $this->dispatcher->dispatch(new ThemeAssetRestrictFilterToVisibility($filter));
            return $result->themeAssetFilter;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function evaluatePostVisibility(ThemeAsset $value): bool
    {
        $this->logDebug("Check if item is visible for Theme asset");
        $span = $this->startSpan("Check if item is visible for  Theme asset");
        try {
            $result = $this->dispatcher->dispatch(new ThemeAssetVisibilityCheck(true, $value));
            return $result->visible;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function prepareVisibleDataCallback(ThemeAsset $content, bool $inlist): ThemeAssetAttributes
    {
        $this->logDebug("Prepare hydration to visible data for Theme asset");
        $span = $this->startSpan("Prepare hydration to visible data for Theme asset");
        try {
            $attributes = $content->toAttributes();
            $result = $this->dispatcher->dispatch(new ThemeAssetEnrichForView($content, $inlist, $attributes));
            return $result->getAttributes();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
